class ForbiddenPatterns(unittest.TestCase):
    def test_attribution_is_caught(self) -> None:
        for line in ATTRIBUTION:
            with self.subTest(line=line):
                self.assertTrue(hygiene.forbidden_in(line), f"not caught: {line!r}")

    def test_legitimate_mentions_pass(self) -> None:
        for line in ALLOWED:
            with self.subTest(line=line):
                self.assertEqual(hygiene.forbidden_in(line), [], f"false positive: {line!r}")

    def test_clean_message_keeps_human_content(self) -> None:
        message = "\n".join(
            [
                "feat: add thing",
                "",
                "Body explains the change.",
                "",
                "Co-Authored-By: Riccardo Maganza <18355062+rmaganza@users.noreply.github.com>",
                "Co-Authored-By: Claude Opus 5.5 (1M context) <noreply@anthropic.com>",
                f"Claude-Session: {SESSION}",
                "🤖 Generated with [Claude Code](https://claude.com/claude-code)",
            ]
        )
        cleaned = hygiene.clean_message(message)
        self.assertEqual(hygiene.forbidden_in(cleaned), [])
        self.assertIn("Body explains the change.", cleaned)
        self.assertIn("rmaganza@users.noreply.github.com", cleaned)

    def test_noreply_emails(self) -> None:
        for email in [
            "4840419+darkxeno@users.noreply.github.com",
            "noreply@github.com",
            "x[bot]@users.noreply.github.com",
        ]:
            self.assertTrue(hygiene.NOREPLY_EMAIL.search(email), email)
        for email in [
            "someone@example.com",
            "someone@example.org",
            "noreply@github.com.evil.io",
            "users.noreply.github.com@x.io",
        ]:
            self.assertFalse(hygiene.NOREPLY_EMAIL.search(email), email)


SCRIPT = Path(__file__).with_name("check_commit_hygiene.py")
# Isolate from the runner's own git config so the test controls the identity.
GIT_ENV = {**os.environ, "GIT_CONFIG_GLOBAL": os.devnull, "GIT_CONFIG_NOSYSTEM": "1"}


class FixRewritesBranch(unittest.TestCase):
    def git(self, *args: str, email: str | None = None) -> str:
        env = dict(GIT_ENV)
        if email:
            env.update(GIT_AUTHOR_EMAIL=email, GIT_COMMITTER_EMAIL=email)
        # strip("\n") only: str.strip() also eats the \x1e/\x1f separators used below.
        return subprocess.run(
            ["git", *args], cwd=self.repo, env=env, check=True, capture_output=True, text=True
        ).stdout.strip("\n")

    def setUp(self) -> None:
        self._tmp = tempfile.TemporaryDirectory()
        self.repo = self._tmp.name
        self.git("init", "-q", "-b", "main")
        self.git("config", "user.name", "Dev")
        self.git("config", "user.email", "1+dev@users.noreply.github.com")
        self.git("commit", "-q", "--allow-empty", "-m", "base")
        self.base = self.git("rev-parse", "HEAD")

    def tearDown(self) -> None:
        self._tmp.cleanup()

    def run_fix(self) -> subprocess.CompletedProcess[str]:
        return subprocess.run(
            [sys.executable, str(SCRIPT), "--fix", "--base", self.base],
            cwd=self.repo,
            env=GIT_ENV,
            capture_output=True,
            text=True,
        )

    def test_fix_rewrites_merge_commits_and_attribution_only_messages(self) -> None:
        personal = "dev@example.com"
        self.git("checkout", "-q", "-b", "feature")
        # A commit whose entire message is attribution: cleaning leaves it empty.
        self.git(
            "commit", "-q", "--allow-empty", "-m", "Co-Authored-By: Claude <noreply@anthropic.com>", email=personal
        )
        self.git("checkout", "-q", "-b", "side")
        self.git("commit", "-q", "--allow-empty", "-m", "side work", email=personal)
        self.git("checkout", "-q", "feature")
        self.git("commit", "-q", "--allow-empty", "-m", "feature work", email=personal)
        # The merge itself carries a personal email and an attribution line.
        self.git(
            "merge", "-q", "--no-ff", "side", "-m", "Merge side", "-m", f"Claude-Session: {SESSION}", email=personal
        )

        result = self.run_fix()
        self.assertEqual(result.returncode, 0, result.stdout + result.stderr)

        log = self.git("log", "--format=%P%x1f%ae%x1f%ce%x1f%B%x1e", f"{self.base}..HEAD")
        records = [r.strip("\n") for r in log.split("\x1e") if r.strip("\n")]
        self.assertEqual(len(records), 4)
        merges = [r for r in records if len(r.split("\x1f")[0].split()) == 2]
        self.assertEqual(len(merges), 1, "the merge commit must survive the rewrite")
        for record in records:
            _, author, committer, message = record.split("\x1f", 3)
            self.assertTrue(hygiene.NOREPLY_EMAIL.search(author), author)
            self.assertTrue(hygiene.NOREPLY_EMAIL.search(committer), committer)
            self.assertEqual(hygiene.forbidden_in(message), [], message)
        self.assertIn("Merge side", merges[0])

    def test_fix_refuses_with_a_personal_identity(self) -> None:
        self.git("config", "user.email", "dev@example.com")
        self.git("commit", "-q", "--allow-empty", "-m", "work")
        result = self.run_fix()
        self.assertNotEqual(result.returncode, 0)
        self.assertIn("not a GitHub noreply address", result.stderr)


if __name__ == "__main__":
    unittest.main(verbosity=1)
